          put(g, cylGeo(0.045, 0.045, 2.0, 6), C.gold, 0, y0, 0).rotation.z = PI / 2;
          put(g, cylGeo(0.045, 0.045, 2.0, 6), C.gold, 0, y0 + 0.8, 0).rotation.z = PI / 2;
          rod(g, -0.7, y0 + 0.8, 0, -0.7, 2.55, 0, 0.01, C.ink);
          rod(g, 0.7, y0 + 0.8, 0, 0.7, 2.55, 0, 0.01, C.ink);
